function shippingCost(method, weightKg) {
  switch (method) {
    case "standard":
      return 4.99 + 0.5 * weightKg;
    case "express":
      return 9.99 + 0.9 * weightKg;
    case "overnight":
      return 24.99 + 1.5 * weightKg;
    default:
      throw new RangeError(`unknown method: ${method}`);
  }
}

function deliveryEstimate(method) {
  switch (method) {
    case "standard":
      return "3-5 business days";
    case "express":
      return "1-2 business days";
    case "overnight":
      return "next business day";
    default:
      throw new RangeError(`unknown method: ${method}`);
  }
}

function methodLabel(method) {
  switch (method) {
    case "standard":
      return "Standard";
    case "express":
      return "Express";
    case "overnight":
      return "Overnight";
    default:
      throw new RangeError(`unknown method: ${method}`);
  }
}

module.exports = { shippingCost, deliveryEstimate, methodLabel };

