const test = require("node:test");
const assert = require("node:assert");

const { shippingCost, deliveryEstimate, methodLabel } = require("./shipping");

test("costs are exact for every method", () => {
  assert.strictEqual(shippingCost("standard", 2), 4.99 + 0.5 * 2);
  assert.strictEqual(shippingCost("express", 10), 9.99 + 0.9 * 10);
  assert.strictEqual(shippingCost("overnight", 0), 24.99);
});

test("estimates and labels unchanged", () => {
  assert.strictEqual(deliveryEstimate("standard"), "3-5 business days");
  assert.strictEqual(deliveryEstimate("express"), "1-2 business days");
  assert.strictEqual(deliveryEstimate("overnight"), "next business day");
  assert.strictEqual(methodLabel("standard"), "Standard");
  assert.strictEqual(methodLabel("express"), "Express");
  assert.strictEqual(methodLabel("overnight"), "Overnight");
});

test("unknown methods throw RangeError from every function", () => {
  for (const fn of [() => shippingCost("drone", 1), () => deliveryEstimate("drone"),
                    () => methodLabel("drone")]) {
    assert.throws(fn, RangeError);
  }
});

test("prototype names are not treated as methods", () => {
  assert.throws(() => methodLabel("toString"), RangeError);
  assert.throws(() => shippingCost("constructor", 1), RangeError);
});

reference_solution.shipping.js:
const METHODS = {
  standard: { base: 4.99, perKg: 0.5, estimate: "3-5 business days", label: "Standard" },
  express: { base: 9.99, perKg: 0.9, estimate: "1-2 business days", label: "Express" },
  overnight: { base: 24.99, perKg: 1.5, estimate: "next business day", label: "Overnight" },
};

function lookup(method) {
  if (!Object.hasOwn(METHODS, method)) {
    throw new RangeError(`unknown method: ${method}`);
  }
  return METHODS[method];
}

function shippingCost(method, weightKg) {
  const { base, perKg } = lookup(method);
  return base + perKg * weightKg;
}

function deliveryEstimate(method) {
  return lookup(method).estimate;
}

function methodLabel(method) {
  return lookup(method).label;
}

module.exports = { shippingCost, deliveryEstimate, methodLabel };

